package org.slavicmyths.verify;
import java.util.*;import java.nio.file.*;import java.util.concurrent.*;
import net.minecraft.server.level.*;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.resources.*;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.structure.*;
import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;
import org.slavicmyths.chud.*;
/** Disposable-world native generation observer. Never calls generate/place or changes terrain. */
@EventBusSubscriber(modid="slavicmyths") public final class Worldgen300 {
 static ServerLevel w;static long began,pre,wait;static boolean done;static int phase,index;static ChunkPos held;static ChudRegionPlanner.Selected selected;
 static final TicketType<Long> TICKET=TicketType.create("qa300",Long::compare);
 static final ExecutorService WORK=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"qa300-plan");t.setDaemon(true);return t;});
 static Future<Optional<ChudRegionPlanner.Selected>> pending;
 static final List<Long> times=new ArrayList<>();static final List<Map<String,Object>> rows=new ArrayList<>();static final Map<String,Object> out=new LinkedHashMap<>();
 static final List<ChunkPos> chunks=new ArrayList<>(); static final List<ChunkPos> heldAll=new ArrayList<>();
 @SubscribeEvent public static void start(net.neoforged.neoforge.event.server.ServerStartedEvent e){if("depth".equals(System.getProperty("slavicmyths.qa300"))||"story".equals(System.getProperty("slavicmyths.qa300"))||"legacy".equals(System.getProperty("slavicmyths.qa300"))||"census".equals(System.getProperty("slavicmyths.qa300"))||"survey".equals(System.getProperty("slavicmyths.qa300"))||System.getProperty("slavicmyths.qa300","").startsWith("yaga"))return;w=e.getServer().overworld();began=System.nanoTime();out.put("seed",w.getSeed());out.put("mode",System.getProperty("slavicmyths.qa300"));}
 @SubscribeEvent public static void pre(net.neoforged.neoforge.event.tick.ServerTickEvent.Pre e){pre=System.nanoTime();}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){if(w==null||done)return;times.add(System.nanoTime()-pre);try{
  if(System.nanoTime()-began>600_000_000_000L)throw new IllegalStateException("10 minute test bound");
  if(phase==0){if(pending==null){var g=w.getChunkSource().getGenerator();var c=new Structure.GenerationContext(w.registryAccess(),g,g.getBiomeSource(),w.getChunkSource().randomState(),w.getStructureManager(),w.getSeed(),new ChunkPos(0,0),w,b->true);pending=WORK.submit(()->{ChudSearchBudget.begin(System.nanoTime()+90_000_000_000L);try{return ChudRegionPlanner.select(c);}finally{ChudSearchBudget.end();}});return;}if(!pending.isDone())return;var s=pending.get();if(s.isEmpty())throw new IllegalStateException("region 0,0 rejected");selected=s.get();out.put("owner",List.of(selected.owner().x,selected.owner().z));out.put("type",selected.city()!=null?"city":selected.abandoned().kind.toString());var box=selected.city()!=null?new ChudPiece(selected.city(),selected.abandoned()).getBoundingBox():selected.abandoned().nativeBounds();if(selected.access()!=null)box=BoundingBox.encapsulatingBoxes(List.of(box,selected.access().bounds)).orElseThrow();out.put("bbox",List.of(box.minX(),box.minY(),box.minZ(),box.maxX(),box.maxY(),box.maxZ()));chunks.add(selected.owner());for(int x=box.minX()>>4;x<=box.maxX()>>4;x++)for(int z=box.minZ()>>4;z<=box.maxZ()>>4;z++){var p=new ChunkPos(x,z);if(!p.equals(selected.owner()))chunks.add(p);}phase=1;return;}
  if(index<chunks.size()){if(held==null){held=chunks.get(index);wait=System.nanoTime();w.getChunkSource().addRegionTicket(TICKET,held,0,300L);return;}var chunk=w.getChunkSource().getChunkNow(held.x,held.z);if(chunk==null){if(System.nanoTime()-wait>120_000_000_000L)throw new IllegalStateException("chunk wait "+held);return;}if(index==0){var id=ResourceLocation.fromNamespaceAndPath("slavicmyths",selected.city()!=null?"chud_city":"chud_abandoned");var st=chunk.getAllStarts().get(w.registryAccess().registryOrThrow(Registries.STRUCTURE).get(id));out.put("native_start",st!=null&&st.isValid());if(st==null||!st.isValid())throw new IllegalStateException("no native start");}heldAll.add(held);held=null;index++;if(index%32==0)System.out.println("QA300 native chunks "+index+"/"+chunks.size());return;}
  BlockPos entrance=selected.city()!=null?selected.city().world(selected.city().points.get(ChudPlan.Role.ENTRANCE)):selected.abandoned().world(selected.abandoned().targets.get("entrance"));
  // Load just the entrance for physical observation after normal generation, never place blocks.
  w.getChunkAt(entrance);int ground=w.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.OCEAN_FLOOR,entrance.getX(),entrance.getZ())-1;
  out.put("entrance",List.of(entrance.getX(),entrance.getY(),entrance.getZ()));out.put("groundY",ground);out.put("entrance_block",w.getBlockState(entrance).toString());out.put("biome",w.getBiome(entrance.atY(ground)).unwrapKey().orElseThrow().location().toString());out.put("surface_access","NOT_RUN physical player traversal"); if(selected.access()!=null){out.put("mouth",selected.access().mouth.toShortString());out.put("route_samples",selected.access().floors.size());int blocked=0;for(var floor:selected.access().floors){boolean ok=false;for(int dy=0;dy<=2;dy++){var q=floor.above(1+dy);if(w.getBlockState(q).getCollisionShape(w,q).isEmpty()&&w.getBlockState(q.above()).getCollisionShape(w,q.above()).isEmpty()&&!w.getBlockState(q.below()).getCollisionShape(w,q.below()).isEmpty()){ok=true;break;}}if(!ok)blocked++;}out.put("blocked_access_samples",blocked);} if(selected.city()!=null)out.put("city_navigation",ChudNavigation.inspect(w,selected.city()));finish(null);
 }catch(Throwable x){finish(x);}}
 static void finish(Throwable x){done=true;WORK.shutdownNow();if(held!=null)w.getChunkSource().removeRegionTicket(TICKET,held,0,300L);for(var p:heldAll)w.getChunkSource().removeRegionTicket(TICKET,p,0,300L);out.put("error",x==null?null:x.toString());out.put("generated_bbox_chunks",index);out.put("elapsed_s",(System.nanoTime()-began)/1e9);Collections.sort(times);out.put("p95_ms",times.isEmpty()?0:times.get((int)(times.size()*.95))/1e6);out.put("max_ms",times.isEmpty()?0:times.getLast()/1e6);try{Files.writeString(Path.of("worldgen300.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));}catch(Exception ex){ex.printStackTrace();}if(x!=null)x.printStackTrace();w.getServer().saveEverything(false,true,true);w.getServer().halt(false);}
}
